SELECT 'UI-SPEC не заведён: назван ли экран — неизвестно' AS detail WHERE NOT EXISTS (SELECT 1 FROM project_documents WHERE project_id = $1 AND entity_kind = 'ui-spec') UNION ALL SELECT s.id || ' — экран есть, а UI-SPEC его не называет' FROM project_screens s WHERE s.project_id = $1 AND EXISTS (SELECT 1 FROM project_documents WHERE project_id = $1 AND entity_kind = 'ui-spec') AND NOT EXISTS (SELECT 1 FROM project_named_id n WHERE n.project_id = s.project_id AND n.entity_kind = 'ui-spec' AND n.said_id = s.id) ORDER BY 1
